function numberOfMatches(n) {
  let total = 0;
  let remaining = n;
  while (remaining > 1) {
    if (remaining % 2 === 0) {
      total += remaining / 2;
      remaining = remaining / 2;
    } else {
      total += (remaining - 1) / 2;
      remaining = (remaining - 1) / 2 + 1;
    }
  }
  return total;
}

